package edu.klh.soa.productlot; import jakarta.persistence.*; @Entity @Table(name="product_lot") public class ProductLot {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String productCode; @Column(nullable=false,unique=true) public String lotCode; @Column(nullable=false) public String supplier; @Column(nullable=false) public String status="AVAILABLE"; protected ProductLot(){} public ProductLot(String p,String l,String s){productCode=p;lotCode=l;supplier=s;}}